    static char[][] grid;
    static int[][] dist; // shortest distance from start to each cell
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};
    static List<Item> items;

    static class Item {
        int x, y, s, e, d;
        Item(int x, int y, int s, int e, int d) {
            this.x = x;
            this.y = y;
            this.s = s;
            this.e = e;
            this.d = d;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        while (true) {
            String[] line = br.readLine().split(" ");
            h = Integer.parseInt(line[0]);
            w = Integer.parseInt(line[1]);
            if (h == 0 && w == 0) break;

            grid = new char[h][w];
            int sx = 0, sy = 0;
            for (int i = 0; i < h; i++) {
                String s = br.readLine();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = s.charAt(j);
                    if (grid[i][j] == 'S') {
                        sx = i; sy = j;
                    }
                }
            }

            int n = Integer.parseInt(br.readLine());
            items = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                line = br.readLine().split(" ");
                int x = Integer.parseInt(line[0]) - 1;
                int y = Integer.parseInt(line[1]) - 1;
                int s = Integer.parseInt(line[2]);
                int e = Integer.parseInt(line[3]);
                int d = Integer.parseInt(line[4]);
                items.add(new Item(x, y, s, e, d));
            }

            // BFS from start to all cells
            dist = new int[h][w];
            for (int[] row : dist) Arrays.fill(row, -1);
            Queue<int[]> q = new LinkedList<>();
            q.offer(new int[]{sx, sy});
            dist[sx][sy] = 0;
            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int x = cur[0], y = cur[1];
                for (int k = 0; k < 4; k++) {
                    int nx = x + dx[k], ny = y + dy[k];
                    if (nx >= 0 && nx < h && ny >= 0 && ny < w && grid[nx][ny] != '#' && dist[nx][ny] == -1) {
                        dist[nx][ny] = dist[x][y] + 1;
                        q.offer(new int[]{nx, ny});
                    }
                }
            }

            // Filter reachable items
            List<Item> reachable = new ArrayList<>();
            for (Item it : items) {
                if (dist[it.x][it.y] != -1) {
                    reachable.add(it);
                }
            }
            int m = reachable.size();

            // DP: dp[t] = max discount achievable at time t
            // Maximum possible time: we need up to max end time + max distance from any item back to start
            int maxEnd = 0;
            for (Item it : reachable) maxEnd = Math.max(maxEnd, it.e);
            int MAX_T = maxEnd + h * w + 5;
            int[] dp = new int[MAX_T + 1];
            Arrays.fill(dp, -1);
            dp[0] = 0;

            // Sort items by end time for processing (optional but helps)
            Collections.sort(reachable, (a, b) -> Integer.compare(a.e, b.e));

            for (Item it : reachable) {
                int travelTo = dist[it.x][it.y];
                // We need to be at item location at some time t where it.s <= t <= it.e
                // We leave start at time 0, arrive at t, must pick immediately then can go elsewhere
                // For each possible arrival time, update dp
                int[] newdp = dp.clone();
                for (int t = 0; t <= MAX_T; t++) {
                    if (dp[t] == -1) continue;
                    int arrive = t + travelTo;
                    if (arrive > it.e) continue;
                    int pickTime = Math.max(arrive, it.s);
                    if (pickTime > it.e) continue;
                    int finishPick = pickTime + 1; // picking takes 1 time unit
                    if (finishPick > MAX_T) continue;
                    newdp[finishPick] = Math.max(newdp[finishPick], dp[t] + it.d);
                }
                dp = newdp;
            }

            int ans = 0;
            for (int t = 0; t <= MAX_T; t++) {
                ans = Math.max(ans, dp[t]);
            }
            System.out.println(ans);
        }
    }
}

