import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MinCostFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        void addEdge(int s, int t, int cap, int cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
        }

        long minCostMaxFlow(int s, int t) {
            long flow = 0, cost = 0;
            int[] dist = new int[n];
            int[] pv = new int[n];
            int[] pe = new int[n];
            boolean[] inq = new boolean[n];

            while (true) {
                Arrays.fill(dist, Integer.MAX_VALUE / 4);
                dist[s] = 0;
                ArrayDeque<Integer> q = new ArrayDeque<>();
                q.add(s);
                inq[s] = true;

                while (!q.isEmpty()) {
                    int v = q.poll();
                    inq[v] = false;
                    for (int i = 0; i < g[v].size(); i++) {
                        Edge e = g[v].get(i);
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            pv[e.to] = v;
                            pe[e.to] = i;
                            if (!inq[e.to]) {
                                inq[e.to] = true;
                                q.add(e.to);
                            }
                        }
                    }
                }

                if (dist[t] >= 0 || dist[t] == Integer.MAX_VALUE / 4) break;

                int add = Integer.MAX_VALUE;
                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    add = Math.min(add, e.cap);
                }
                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    e.cap -= add;
                    g[v].get(e.rev).cap += add;
                }
                flow += add;
                cost += (long) add * dist[t];
            }
            return cost;
        }
    }

    static int H, W;
    static int[][] grid;
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    static int bfsDist(int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) return 0;
        int[][] dist = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(dist[i], -1);
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sr, sc});
        dist[sr][sc] = 0;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == -1) continue;
                if (dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[r][c] + 1;
                if (nr == tr && nc == tc) return dist[nr][nc];
                q.add(new int[]{nr, nc});
            }
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            H = fs.nextInt();
            W = fs.nextInt();
            if (H == 0 && W == 0) break;

            grid = new int[H][W];
            int maxId = 0;
            int startR = -1, startC = -1;

            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    int x = fs.nextInt();
                    grid[i][j] = x;
                    if (x > 0) maxId = Math.max(maxId, x);
                    if (x == 0) {
                        startR = i;
                        startC = j;
                    }
                }
            }

            int n = fs.nextInt();

            int[] itemR = new int[maxId + 1];
            int[] itemC = new int[maxId + 1];
            Arrays.fill(itemR, -1);

            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] > 0) {
                        itemR[grid[i][j]] = i;
                        itemC[grid[i][j]] = j;
                    }
                }
            }

            int[] s = new int[n];
            int[] t = new int[n];
            int[] p = new int[n];
            int[] v = new int[n];

            for (int i = 0; i < n; i++) {
                p[i] = fs.nextInt();
                s[i] = fs.nextInt();
                t[i] = fs.nextInt();
                v[i] = fs.nextInt();
            }

            int[] distStart = new int[n];
            for (int i = 0; i < n; i++) {
                distStart[i] = bfsDist(startR, startC, itemR[p[i]], itemC[p[i]]);
            }

            int[][] dist = new int[n][n];
            for (int i = 0; i < n; i++) {
                int r1 = itemR[p[i]], c1 = itemC[p[i]];
                for (int j = 0; j < n; j++) {
                    int r2 = itemR[p[j]], c2 = itemC[p[j]];
                    dist[i][j] = bfsDist(r1, c1, r2, c2);
                }
            }

            int SRC = 2 * n;
            int SNK = 2 * n + 1;
            MinCostFlow mcf = new MinCostFlow(2 * n + 2);

            for (int i = 0; i < n; i++) {
                int in = i;
                int outNode = i + n;
                mcf.addEdge(in, outNode, 1, -v[i]);
                mcf.addEdge(SRC, in, 1, 0);
                mcf.addEdge(outNode, SNK, 1, 0);
            }

            for (int i = 0; i < n; i++) {
                if (distStart[i] != -1 && distStart[i] <= t[i]) {
                    // reachable from start; can wait until any time in [s[i], t[i]]
                    // represented by source -> i already
                } else {
                    // disable unreachable first pickup
                    // easiest: do not allow source->i
                    mcf.g[SRC].remove(mcf.g[SRC].size() - (n - i)); // not safe
                }
            }

            // Rebuild source edges correctly
            mcf = new MinCostFlow(2 * n + 2);
            for (int i = 0; i < n; i++) {
                int in = i;
                int outNode = i + n;
                mcf.addEdge(in, outNode, 1, -v[i]);
                if (distStart[i] != -1 && distStart[i] <= t[i]) {
                    mcf.addEdge(SRC, in, 1, 0);
                }
                mcf.addEdge(outNode, SNK, 1, 0);
            }

            for (int i = 0; i < n; i++) {
                if (distStart[i] == -1 || distStart[i] > t[i]) continue;
                for (int j = 0; j < n; j++) {
                    if (i == j || dist[i][j] == -1) continue;

                    int earliestFinishI = Math.max(s[i], distStart[i]);
                    // Existence of some time x in [max(s[i],distStart[i]), t[i]]
                    // such that x + dist[i][j] <= t[j]
                    // equivalent to earliestFinishI + dist[i][j] <= t[j]
                    if (earliestFinishI + dist[i][j] <= t[j]) {
                        mcf.addEdge(i + n, j, 1, 0);
                    }
                }
            }

            // More accurate transition check between any two tasks:
            // if there exists xi in [s[i], t[i]] and xj in [s[j], t[j]]
            // with xj >= xi + dist[i][j], then possible iff s.t.
            // max(s[i], some reachable time to i) matters.
            // Since any selected predecessor chain determines actual time,
            // DAG based only on windows works using t-feasibility:
            // xi can be any <= t[i], so edge if s[i] + dist <= t[j]? Not enough.
            // To preserve correctness for chains, rebuild using standard condition:
            // there exists completion time at i not earlier than s[i], and then move to j.
            // Since waiting is allowed, edge i->j iff s[i] + dist[i][j] <= t[j] and s[i] <= t[i].
            // However start reachability also matters. We'll use this standard condition.

            mcf = new MinCostFlow(2 * n + 2);
            for (int i = 0; i < n; i++) {
                int in = i, outNode = i + n;
                mcf.addEdge(in, outNode, 1, -v[i]);
                if (distStart[i] != -1 && distStart[i] <= t[i]) {
                    mcf.addEdge(SRC, in, 1, 0);
                }
                mcf.addEdge(outNode, SNK, 1, 0);
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j || dist[i][j] == -1) continue;
                    if (s[i] + dist[i][j] <= t[j]) {
                        mcf.addEdge(i + n, j, 1, 0);
                    }
                }
            }

            long minCost = mcf.minCostMaxFlow(SRC, SNK);
            out.append(-minCost).append('\n');
        }

        System.out.print(out.toString());
    }
}

