#define MAX_H 30
#define MAX_W 30
#define MAX_ITEMS 400
#define MAX_TIME 1000
#define INF -1000000000

typedef struct {
    int r, c, s, e, v;
} Item;

int H, W, T;
char grid[MAX_H][MAX_W + 1];
int item_id[MAX_H][MAX_W];
Item items[MAX_ITEMS];
int item_count;
int dp[MAX_TIME + 1][MAX_ITEMS + 1];
int dist[MAX_ITEMS][MAX_ITEMS];
int start_dist[MAX_ITEMS];
int end_dist[MAX_ITEMS];
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

int bfs_dist(int sr, int sc, int tr, int tc) {
    if (sr == tr && sc == tc) return 0;
    int qr[MAX_H * MAX_W], qc[MAX_H * MAX_W];
    int d[MAX_H][MAX_W];
    memset(d, -1, sizeof(d));
    int front = 0, rear = 0;
    qr[rear] = sr; qc[rear] = sc; rear++;
    d[sr][sc] = 0;
    while (front < rear) {
        int r = qr[front], c = qc[front]; front++;
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < H && nc >= 0 && nc < W && grid[nr][nc] != '#' && d[nr][nc] == -1) {
                d[nr][nc] = d[r][c] + 1;
                if (nr == tr && nc == tc) return d[nr][nc];
                qr[rear] = nr; qc[rear] = nc; rear++;
            }
        }
    }
    return -1;
}

int max(int a, int b) { return a > b ? a : b; }

int solve() {
    // Map items to indices
    item_count = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                item_id[i][j] = item_count;
                items[item_count].r = i;
                items[item_count].c = j;
                items[item_count].s = 0;
                items[item_count].e = T;
                items[item_count].v = grid[i][j] - '0';
                item_count++;
            }
        }
    }

    // Read time sale info
    int K;
    scanf("%d", &K);
    for (int i = 0; i < K; i++) {
        int r, c, s, e, v;
        scanf("%d %d %d %d %d", &r, &c, &s, &e, &v);
        r--; c--;
        if (grid[r][c] >= '0' && grid[r][c] <= '9') {
            int idx = item_id[r][c];
            items[idx].s = s;
            items[idx].e = e;
            items[idx].v = v;
        }
    }

    // Precompute distances between all items and from start (0,0) to items
    for (int i = 0; i < item_count; i++) {
        start_dist[i] = bfs_dist(0, 0, items[i].r, items[i].c);
        for (int j = 0; j < item_count; j++) {
            dist[i][j] = bfs_dist(items[i].r, items[i].c, items[j].r, items[j].c);
        }
    }

    // DP: dp[t][i] = max value ending at item i at time t (or less)
    // Initialize with -inf
    for (int t = 0; t <= T; t++) {
        for (int i = 0; i <= item_count; i++) {
            dp[t][i] = INF;
        }
    }
    // dummy start item (index item_count) represents position (0,0) with zero value
    int start_idx = item_count;
    dp[0][start_idx] = 0;

    int ans = 0;

    // For each time, we can either stay or move
    for (int t = 0; t <= T; t++) {
        // First, propagate staying in place (time passes)
        if (t > 0) {
            for (int i = 0; i <= item_count; i++) {
                dp[t][i] = max(dp[t][i], dp[t-1][i]);
            }
        }

        // Try to pick items at this time
        for (int i = 0; i < item_count; i++) {
            if (t >= items[i].s && t <= items[i].e) {
                // We can come from any previous state
                for (int j = 0; j <= item_count; j++) {
                    int needed_time;
                    if (j == start_idx) {
                        needed_time = start_dist[i];
                    } else {
                        needed_time = dist[j][i];
                    }
                    if (needed_time == -1) continue;
                    int prev_t = t - needed_time;
                    if (prev_t < 0) continue;
                    if (dp[prev_t][j] != INF) {
                        dp[t][i] = max(dp[t][i], dp[prev_t][j] + items[i].v);
                    }
                }
            }
            ans = max(ans, dp[t][i]);
        }
        // Also consider staying at start
        ans = max(ans, dp[t][start_idx]);
    }

    return ans;
}

int main() {
    while (1) {
        scanf("%d %d", &H, &W);
        if (H == 0 && W == 0) break;
        scanf("%d", &T);
        for (int i = 0; i < H; i++) {
            scanf("%s", grid[i]);
        }
        int result = solve();
        printf("%d\n", result);
    }
    return 0;
}

