#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 1000000000
#define NEG_INF (-1000000000)

typedef struct {
    int x, y;
} Point;

typedef struct {
    int to, next, cap, cost;
} Edge;

static void add_edge(Edge *edges, int *head, int *ecnt, int u, int v, int cap, int cost) {
    edges[*ecnt].to = v;
    edges[*ecnt].cap = cap;
    edges[*ecnt].cost = cost;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;

    edges[*ecnt].to = u;
    edges[*ecnt].cap = 0;
    edges[*ecnt].cost = -cost;
    edges[*ecnt].next = head[v];
    head[v] = (*ecnt)++;
}

static int max_cost_flow(int N, int S, int T, Edge *edges, int *head) {
    int result = 0;
    int *dist = (int*)malloc(sizeof(int) * N);
    int *inq = (int*)malloc(sizeof(int) * N);
    int *pv_v = (int*)malloc(sizeof(int) * N);
    int *pv_e = (int*)malloc(sizeof(int) * N);
    int *q = (int*)malloc(sizeof(int) * N);

    while (1) {
        for (int i = 0; i < N; i++) {
            dist[i] = NEG_INF;
            inq[i] = 0;
        }
        dist[S] = 0;

        int qh = 0, qt = 0;
        q[qt++] = S;
        inq[S] = 1;

        while (qh != qt) {
            int v = q[qh++];
            if (qh == N) qh = 0;
            inq[v] = 0;

            for (int e = head[v]; e != -1; e = edges[e].next) {
                if (edges[e].cap <= 0) continue;
                int to = edges[e].to;
                int nd = dist[v] + edges[e].cost;
                if (nd > dist[to]) {
                    dist[to] = nd;
                    pv_v[to] = v;
                    pv_e[to] = e;
                    if (!inq[to]) {
                        q[qt++] = to;
                        if (qt == N) qt = 0;
                        inq[to] = 1;
                    }
                }
            }
        }

        if (dist[T] <= 0) break;

        int f = INF;
        for (int v = T; v != S; v = pv_v[v]) {
            if (edges[pv_e[v]].cap < f) f = edges[pv_e[v]].cap;
        }
        for (int v = T; v != S; v = pv_v[v]) {
            int e = pv_e[v];
            edges[e].cap -= f;
            edges[e ^ 1].cap += f;
        }
        result += dist[T] * f;
    }

    free(dist);
    free(inq);
    free(pv_v);
    free(pv_e);
    free(q);
    return result;
}

