        int ncell = 0;
        int sx = -1, sy = -1;

        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                if (grid[y][x] != '#') {
                    id[y][x] = ncell;
                    cells[ncell].x = x;
                    cells[ncell].y = y;
                    if (grid[y][x] == 'S') {
                        sx = x; sy = y;
                    }
                    ncell++;
                }
            }
        }

        int K;
        scanf("%d", &K);

        int *tx = (int*)malloc(sizeof(int) * K);
        int *ty = (int*)malloc(sizeof(int) * K);
        int *ts = (int*)malloc(sizeof(int) * K);
        int *te = (int*)malloc(sizeof(int) * K);
        int *val = (int*)malloc(sizeof(int) * K);

        for (int i = 0; i < K; i++) {
            scanf("%d %d %d %d %d", &tx[i], &ty[i], &ts[i], &te[i], &val[i]);
            tx[i]--;
            ty[i]--;
        }

        int startId = id[sy][sx];

        int *distStart = (int*)malloc(sizeof(int) * ncell);
        int **distAll = (int**)malloc(sizeof(int*) * K);

        int *queue = (int*)malloc(sizeof(int) * ncell);

        // BFS from start
        for (int i = 0; i < ncell; i++) distStart[i] = INF;
        distStart[startId] = 0;
        int qh = 0, qt = 0;
        queue[qt++] = startId;
        while (qh < qt) {
            int v = queue[qh++];
            int x = cells[v].x, y = cells[v].y;
            const int dx[4] = {1, -1, 0, 0};
            const int dy[4] = {0, 0, 1, -1};
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
                if (id[ny][nx] == -1) continue;
                int to = id[ny][nx];
                if (distStart[to] == INF) {
                    distStart[to] = distStart[v] + 1;
                    queue[qt++] = to;
                }
            }
        }

        for (int i = 0; i < K; i++) {
            distAll[i] = (int*)malloc(sizeof(int) * ncell);
            for (int j = 0; j < ncell; j++) distAll[i][j] = INF;

            int sid = id[ty[i]][tx[i]];
            if (sid == -1) continue;

            distAll[i][sid] = 0;
            qh = qt = 0;
            queue[qt++] = sid;
            while (qh < qt) {
                int v = queue[qh++];
                int x = cells[v].x, y = cells[v].y;
                const int dx[4] = {1, -1, 0, 0};
                const int dy[4] = {0, 0, 1, -1};
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
                    if (id[ny][nx] == -1) continue;
                    int to = id[ny][nx];
                    if (distAll[i][to] == INF) {
                        distAll[i][to] = distAll[i][v] + 1;
                        queue[qt++] = to;
                    }
                }
            }
        }

        // Build DAG of feasible item pickups in time order and solve max weight path cover as longest path in DAG.
        // Simpler: DP over events sorted by end time.
        int *reachable = (int*)calloc(K, sizeof(int));
        int *dp = (int*)malloc(sizeof(int) * K);
        int ans = 0;

        for (int i = 0; i < K; i++) {
            dp[i] = NEG_INF;
            int cid = id[ty[i]][tx[i]];
            if (cid != -1 && distStart[cid] != INF) {
                int arrive = distStart[cid];
                if (ts[i] <= arrive && arrive <= te[i]) {
                    dp[i] = val[i];
                    reachable[i] = 1;
                    if (dp[i] > ans) ans = dp[i];
                }
            }
        }

        for (int iter = 0; iter < K; iter++) {
            int updated = 0;
            for (int i = 0; i < K; i++) {
                if (dp[i] == NEG_INF) continue;
                int fromId = id[ty[i]][tx[i]];
                for (int j = 0; j < K; j++) {
                    if (i == j) continue;
                    int toId = id[ty[j]][tx[j]];
                    if (fromId == -1 || toId == -1) continue;
                    int d = distAll[i][toId];
                    if (d == INF) continue;
                    int arrive = ts[i] + d;
                    if (arrive < ts[j]) arrive = ts[j];
                    if (arrive <= te[j]) {
                        if (dp[j] < dp[i] + val[j]) {
                            dp[j] = dp[i] + val[j];
                            if (dp[j] > ans) ans = dp[j];
                            updated = 1;
                        }
                    }
                }
            }
            if (!updated) break;
        }

        printf("%d\n", ans);

        free(dp);
        free(reachable);
        free(queue);
        for (int i = 0; i < K; i++) free(distAll[i]);
        free(distAll);
        free(distStart);
        free(tx); free(ty); free(ts); free(te); free(val);
        free(cells);
        for (int i = 0; i < H; i++) free(id[i]);
        free(id);
        for (int i = 0; i < H; i++) free(grid[i]);
        free(grid);
    }

    return 0;
}

