            for (int d = 0; d < 4; d++) {
                int ny = y + dy[d], nx = x + dx[d];
                if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
                if (grid[ny][nx] == '#') continue;
                if (distStart[ny][nx] > distStart[y][x] + 1) {
                    distStart[ny][nx] = distStart[y][x] + 1;
                    q.push({ny, nx});
                }
            }
        }

        // BFS between item cells and also from item to start
        // Build graph: nodes 0..N-1 for items, plus node N for start (virtual)
        int V = N + 1;
        vector<vector<int>> dist(V, vector<int>(V, INF));
        // distances from start to each item
        for (int i = 0; i < N; i++) {
            if (distStart[itemY[i]][itemX[i]] < INF) {
                dist[N][i] = distStart[itemY[i]][itemX[i]];
            }
        }

        // distances between items
        for (int i = 0; i < N; i++) {
            // BFS from item i
            vector<vector<int>> d(H, vector<int>(W, INF));
            queue<pair<int,int>> q;
            d[itemY[i]][itemX[i]] = 0;
            q.push({itemY[i], itemX[i]});
            while (!q.empty()) {
                auto [y, x] = q.front(); q.pop();
                for (int dir = 0; dir < 4; dir++) {
                    int ny = y + dy[dir], nx = x + dx[dir];
                    if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
                    if (grid[ny][nx] == '#') continue;
                    if (d[ny][nx] > d[y][x] + 1) {
                        d[ny][nx] = d[y][x] + 1;
                        q.push({ny, nx});
                    }
                }
            }
            for (int j = 0; j < N; j++) {
                if (i != j && d[itemY[j]][itemX[j]] < INF) {
                    dist[i][j] = d[itemY[j]][itemX[j]];
                }
            }
        }

        // DP over subsets
        int maxMask = 1 << N;
        vector<vector<int>> dp(maxMask, vector<int>(N, -INF));
        // Initialize: start at item i at time = dist[N][i] if <= end[i]
        for (int i = 0; i < N; i++) {
            if (dist[N][i] <= end[i]) {
                dp[1 << i][i] = max(dp[1 << i][i], disc[i]);
            }
        }

        int ans = 0;
        for (int mask = 0; mask < maxMask; mask++) {
            for (int last = 0; last < N; last++) {
                if (!(mask & (1 << last))) continue;
                int curTime = 0; // We need to track time. Actually we need time to compute.
                // But dp stores only discount sum, not time. So we need to store time as well.
                // Let's redefine dp as pair (time, discount) or store min time to achieve discount.
                // Better: dp[mask][last] = minimum time needed to collect mask ending at last.
            }
        }

        // Redo DP with time tracking
        vector<vector<int>> dpTime(maxMask, vector<int>(N, INF));
        vector<vector<int>> dpVal(maxMask, vector<int>(N, 0));
        for (int i = 0; i < N; i++) {
            if (dist[N][i] <= end[i]) {
                int t = max(start[i], dist[N][i]);
                if (t <= end[i]) {
                    dpTime[1 << i][i] = t;
                    dpVal[1 << i][i] = disc[i];
                    ans = max(ans, disc[i]);
                }
            }
        }

        for (int mask = 0; mask < maxMask; mask++) {
            for (int last = 0; last < N; last++) {
                if (!(mask & (1 << last))) continue;
                if (dpTime[mask][last] == INF) continue;
                int curTime = dpTime[mask][last];
                int curVal = dpVal[mask][last];
                ans = max(ans, curVal);
                for (int nxt = 0; nxt < N; nxt++) {
                    if (mask & (1 << nxt)) continue;
                    if (dist[last][nxt] == INF) continue;
                    int arrival = curTime + dist[last][nxt];
                    if (arrival > end[nxt]) continue;
                    int pickTime = max(arrival, start[nxt]);
                    if (pickTime > end[nxt]) continue;
                    int newMask = mask | (1 << nxt);
                    if (dpTime[newMask][nxt] > pickTime) {
                        dpTime[newMask][nxt] = pickTime;
                        dpVal[newMask][nxt] = curVal + disc[nxt];
                    } else if (dpTime[newMask][nxt] == pickTime) {
                        dpVal[newMask][nxt] = max(dpVal[newMask][nxt], curVal + disc[nxt]);
                    }
                }
            }
        }

        cout << ans << "\n";
    }

    return 0;
}

