        int M = items.size();
        // dp[r][c][t][mask] = max discount
        // Use BFS/map
        map<tuple<int,int,int,int>, int> dp;
        queue<tuple<int,int,int,int>> q;
        auto start_state = make_tuple(sr, sc, 0, 0);
        dp[start_state] = 0;
