using ll = long long;

struct Edge {
    int to, rev;
    ll cap, cost;
};

struct MinCostFlow {
    int N;
    vector<vector<Edge>> g;
    MinCostFlow(int n) : N(n), g(n) {}

    void addEdge(int s, int t, ll cap, ll cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    pair<ll,ll> minCostMaxFlow(int s, int t) {
        const ll INF = (1LL << 60);
        ll flow = 0, cost = 0;
        vector<ll> dist(N), pot(N, 0);
        vector<int> pv(N), pe(N);

        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;
                    ll nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;
            for (int i = 0; i < N; ++i) {
                if (dist[i] < INF) pot[i] += dist[i];
            }

            ll add = INF;
            for (int v = t; v != s; v = pv[v]) {
                add = min(add, g[pv[v]][pe[v]].cap);
            }
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
                cost += add * e.cost;
            }
            flow += add;
        }
        return {flow, cost};
    }
};

