                if (max(dist[startCell][itemCell[i]], S[i]) <= T[i]) firstOK[i] = 1;
            }
        }

        // Maximum total value of a path in DAG with arbitrary starts.
        // Need acyclic order by time windows; use edges only if S[i] <= S[j] and feasible.
        // To ensure DAG, sort by S then T and only allow forward edges.
        vector<int> ord(M);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b) {
            if (S[a] != S[b]) return S[a] < S[b];
            if (T[a] != T[b]) return T[a] < T[b];
