                // dp alone doesn't track actual arrival time, so this simple DP is insufficient.
            }
        }

        // Correct approach: weighted interval-like DP on events with state per item using earliest possible time.
        // Since value only depends on chosen items and all windows are intervals, use longest path in DAG where
        // node i can precede j if taking i at its earliest possible time still allows j.
        // Earliest possible take time of i as first:
        vector<ll> firstTake(M, (ll)INF);
        for (int i = 0; i < M; ++i) {
            if (startCell != -1 && dist[startCell][itemCell[i]] < INF) {
                ll t = max((ll)dist[startCell][itemCell[i]], (ll)S[i]);
                if (t <= T[i]) firstTake[i] = t;
            }
        }

        // Relax in sorted order: best value ending at i, and among equal/better values, smallest take time.
        vector<ll> bestVal(M, -1), bestTime(M, (ll)INF);
        for (int ii = 0; ii < M; ++ii) {
            int i = ord[ii];
            if (firstTake[i] < INF) {
                bestVal[i] = V[i];
                bestTime[i] = firstTake[i];
            }
            for (int jj = 0; jj < ii; ++jj) {
