    # BFS distances from each numbered cell to every cell
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    dist_between = [[INF] * (N + 1) for _ in range(N + 1)]

    for s in range(1, N + 1):
        sx, sy = pos[s]
        dist = [[-1] * W for _ in range(H)]
        q = deque()
        q.append((sx, sy))
        dist[sx][sy] = 0

        while q:
            x, y = q.popleft()
            d = dist[x][y] + 1
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and dist[nx][ny] == -1 and grid[nx][ny] != -1:
                    dist[nx][ny] = d
                    q.append((nx, ny))

        for t in range(1, N + 1):
            tx, ty = pos[t]
            if dist[tx][ty] != -1:
                dist_between[s][t] = dist[tx][ty]

    # sales[i] = (s, e, a)
    # DP over subsets: can arrive at item i by time <= e_i, collecting exactly subset and ending at i
    size = 1 << N
    dp = [[INF] * N for _ in range(size)]
    ans = 0

    for i in range(N):
        s, e, a = sales[i]
        # start at item i at time 0, can wait until s and buy at s if reachable from itself (always)
        if s <= e:
            dp[1 << i][i] = s
            if a > ans:
                ans = a

    sum_val = [0] * size
    for mask in range(1, size):
        b = mask & -mask
        idx = (b.bit_length() - 1)
        sum_val[mask] = sum_val[mask ^ b] + sales[idx][2]

    for mask in range(size):
        for last in range(N):
            cur_time = dp[mask][last]
            if cur_time == INF:
                continue
            if sum_val[mask] > ans:
                ans = sum_val[mask]

            last_item = last + 1
            for nxt in range(N):
                if (mask >> nxt) & 1:
                    continue
                d = dist_between[last_item][nxt + 1]
                if d >= INF:
                    continue
                s, e, a = sales[nxt]
                arrive = cur_time + d
                buy_time = max(arrive, s)
                if buy_time <= e:
                    nmask = mask | (1 << nxt)
                    if buy_time < dp[nmask][nxt]:
                        dp[nmask][nxt] = buy_time

    return ans

def main():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out = []

    while True:
        try:
            H = int(next(it))
            W = int(next(it))
        except StopIteration:
            break
        if H == 0 and W == 0:
            break

        grid = []
        maxnum = 0
        for _ in range(H):
            row = [int(next(it)) for _ in range(W)]
            grid.append(row)
            for v in row:
                if v > maxnum:
                    maxnum = v

        N = int(next(it))
        sales = []
        for _ in range(N):
            s = int(next(it))
            e = int(next(it))
            a = int(next(it))
            sales.append((s, e, a))

        out.append(str(solve_case(H, W, grid, N, sales)))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
